def somar4(a,b):
    out=0; carry=0
    for i in range(4):
        x=(a>>i)&1; y=(b>>i)&1
        s=x^y^carry
        carry=(x&y)|((x^y)&carry)
        out|=s<<i
    return out,carry
for a in range(16):
    for b in range(16):
        out,c=somar4(a,b)
        assert out+16*c==a+b
